SELECT NVL(T.PRICE, NVL(T.NETPRICE, 0)) PRICE,
	   NVL(T.M_DURATION, 0) DURATION
  FROM MST_BOND_VALUATION_INFO T
 WHERE T.SEC_ID = #{secid, jdbcType=VARCHAR}
   AND T.VALUE_SOURCE = #{vlsrc, jdbcType=VARCHAR}
   AND T.VALUE_DATE = (SELECT MAX(T.VALUE_DATE)
                       	 FROM MST_BOND_VALUATION_INFO F
                      	WHERE F.SEC_ID = #{secid, jdbcType=VARCHAR}
                      	  AND F.VALUE_SOURCE = #{vlsrc, jdbcType=VARCHAR}
                          AND F.VALUE_DATE <= #{vldate, jdbcType=DATE})

SELECT NVL(T.AMOUNT, 0)
  FROM PTL_SEC_POSITION T
 WHERE T.HODING_TYPE = '03'
   AND T.PORTFOLIO_ID = #{ptlid, jdbcType=VARCHAR}
   AND T.FINPROD_ID = #{finprodid, jdbcType=VARCHAR}
   AND T.CDATE + 1 = #{cdate, jdbcType=DATE}

SELECT NVL(T.TDY_FLOAT_INGPL, 0) + NVL(T.DSC_COST_AMT, 0) + NVL(T.TDY_INTINCEXP, 0) T_1VALUE,
	   NVL(T.ACT_D_YIELD, 0) ACTYIELD,
	   NVL(T.TDY_INTINCEXP, 0) INTAMT,
	   NVL(T.DSC_COST_AMT, 0) NETAMT
  FROM PTL_SEC_VALUTION T
 WHERE T.PORTFOLIO_ID = #{ptlid, jdbcType=VARCHAR}
   AND T.FINPROD_ID = #{finprodid, jdbcType=VARCHAR}
   AND T.CDATE + 1 = #{cdate, jdbcType=DATE}

SELECT T.FINPROD_ID FINPRODID, SUM(NVL(T.TRADE_AMT, 0))
  FROM TRD_PRODUCT_DEAL T
 WHERE T.FINPROD_ID = #{finprodid, jdbcType=VARCHAR}
   AND T.SETTLE_DATE <= #{settDate, jdbcType=DATE}
   AND T.FINPROD_TYPE2 != 'F16'
   AND T.PS IN ('T01', 'T04')
 GROUP BY T.FINPROD_ID;

SELECT NVL(T.TDY_UNIT_VALUE, 0)
  FROM BOK_POSITION_PRD T
 WHERE T.FINPROD_ID = #{finprodid, jdbcType=VARCHAR}
   AND T.CDATE = #{cdate, jdbcType=DATE}
